CREATE TYPE public.app_role AS ENUM ('student','teacher','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'Campus member');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.teacher_requests (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, display_name text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.teacher_requests TO authenticated; GRANT ALL ON public.teacher_requests TO service_role;
ALTER TABLE public.teacher_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY request_read ON public.teacher_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY request_insert ON public.teacher_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND NOT public.has_role(auth.uid(),'teacher'));
CREATE FUNCTION public.register_campus_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(nullif(left(trim(NEW.raw_user_meta_data->>'display_name'),100),''),nullif(left(NEW.raw_user_meta_data->>'full_name',100),''),'Campus member')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'student'); IF NEW.raw_user_meta_data->>'requested_role'='teacher' THEN INSERT INTO public.teacher_requests(user_id,display_name) SELECT id,display_name FROM public.profiles WHERE id=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER campus_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.register_campus_user();
CREATE FUNCTION public.review_teacher(_user_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.teacher_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END WHERE user_id=_user_id AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'No pending request'; END IF; IF _approve THEN INSERT INTO public.user_roles(user_id,role) VALUES(_user_id,'teacher') ON CONFLICT DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_teacher(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_teacher(uuid,boolean) TO authenticated;
CREATE TABLE public.assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), teacher_id uuid NOT NULL REFERENCES public.profiles(id), teacher_name text NOT NULL, title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 120), description text NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 10000), due_date date NOT NULL, image_path text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(image_path IS NULL OR image_path LIKE teacher_id::text || '/%'));
GRANT SELECT,INSERT,DELETE ON public.assignments TO authenticated; GRANT ALL ON public.assignments TO service_role;
ALTER TABLE public.assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY assignment_read ON public.assignments FOR SELECT TO authenticated USING(true);
CREATE POLICY teacher_create ON public.assignments FOR INSERT TO authenticated WITH CHECK(teacher_id=auth.uid() AND public.has_role(auth.uid(),'teacher'));
CREATE POLICY teacher_delete ON public.assignments FOR DELETE TO authenticated USING(teacher_id=auth.uid() AND public.has_role(auth.uid(),'teacher'));
CREATE INDEX assignments_due_date ON public.assignments(due_date);
CREATE POLICY assignment_images_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='assignment-images' AND (EXISTS(SELECT 1 FROM public.assignments a WHERE a.image_path=name) OR ((storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'teacher'))));
CREATE POLICY assignment_images_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='assignment-images' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'teacher') AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY assignment_images_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='assignment-images' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'teacher'));
ALTER PUBLICATION supabase_realtime ADD TABLE public.assignments;